126	/// Re-observes root, config, package discovery, manifests, Git evidence, and
127	/// the exact operation DAG before creating an opaque authorization capability.
128	pub fn validate_release_intent<L: ProjectLocator, R: CommandRunner>(
129	    root: &Path,
130	    locator: &L,
131	    runner: &R,
132	    selection: &ReleaseSelection,
133	    received: ReleaseIntentV1,
134	) -> Result<ValidatedReleaseIntent, GraphError> {
135	    let root = canonical_root(root)?;
136	    let workspace = Workspace::load(root.clone(), locator, runner)?;
137	    let source = observe_source(&workspace, received.trust_profile)?;
138	    let (expected, prepared) =
139	        derive_release_intent_with_prepared(&workspace, selection, source.clone(), received.trust_profile)?;
140	    if expected != received || observe_source(&workspace, received.trust_profile)? != source {
141	        return Err(GraphError::ReleaseIntentStale);
142	    }
143	
144	    Ok(ValidatedReleaseIntent {
145	        prepared: PreparedReleaseInputs {
146	            root,
147	            source,
148	            operations: prepared,
149	        },
150	        intent: received,
151	    })
152	}
