154	fn canonical_root(root: &Path) -> Result<std::path::PathBuf, GraphError> {
155	    dunce::canonicalize(root).map_err(|error| GraphError::ReleaseInputRead {
156	        path: root.to_path_buf(),
157	        message: error.to_string(),
158	    })
159	}
