384	fn package_fingerprint<R: CommandRunner, D: DependencyResolver>(
385	    workspace: &Workspace<'_, R, D>,
386	    id: &ReleasePackageId,
387	    package: &callisto_model::Package,
388	    version: &Version,
389	) -> Result<SemanticInputDigest, GraphError> {
390	    let mut transcript = CanonicalTranscript::semantic_input_v1();
391	    transcript.push_str("package.id", &id.to_string());
392	    transcript.push_str("package.version", version.render());
393	    for manifest in &package.manifests {
394	        let path = workspace.root.join(&manifest.path);
395	        let bytes = std::fs::read(&path).map_err(|error| GraphError::ReleaseInputRead {
396	            path: manifest.path.clone(),
397	            message: error.to_string(),
398	        })?;
399	        transcript.push_str("manifest.path", &manifest.path.display().to_string());
400	        transcript.push_str("manifest.bytes", digest_bytes("manifest", &bytes).as_str());
401	        transcript.push_str("manifest.role", &manifest_role_text(&manifest.role));
402	        transcript.push_str("manifest.format", manifest.format.ecosystem().prefix());
403	    }
404	    transcript.push_str("package.trigger", release_trigger_text(package.release_trigger));
405	    transcript.push_str(
406	        "package.tag",
407	        &package
408	            .tag_template
409	            .as_ref()
410	            .map_or_else(|| "default".to_string(), |tag| tag.as_str()),
411	    );
412	    for target in &package.publish_to {
413	        transcript.push_str("package.target", target_fingerprint(workspace, target)?.as_str());
414	    }
415	    Ok(SemanticInputDigest::from_transcript(&transcript))
416	}
