345	/// The versioned semantic input projection built and compared by callisto-graph.
346	///
347	/// This model deliberately stores only already-derived fingerprints. Graph is
348	/// responsible for selecting the complete set of components and never puts
349	/// raw endpoints, credentials, command lines, or environment values here.
350	#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
351	#[serde(rename_all = "camelCase", deny_unknown_fields)]
352	pub struct ReleaseInputSnapshotV1 {
353	    pub schema_version: u8,
354	    pub source: SourceIdentity,
355	    pub components: Vec<ReleaseInputComponentV1>,
356	}
357	
358	impl ReleaseInputSnapshotV1 {
359	    pub const SCHEMA_VERSION: u8 = 1;
360	
361	    pub fn new(source: SourceIdentity, mut components: Vec<ReleaseInputComponentV1>) -> Self {
362	        components.sort();
363	        components.dedup();
364	        Self {
365	            schema_version: Self::SCHEMA_VERSION,
366	            source,
367	            components,
368	        }
369	    }
370	
371	    pub fn digest(&self) -> SemanticInputDigest {
372	        let mut transcript = CanonicalTranscript::semantic_input_v1();
373	        transcript.push_bytes("schema", [self.schema_version]);
374	        match &self.source {
375	            SourceIdentity::GitCommit { sha } => transcript.push_str("source.git", sha.as_str()),
376	            SourceIdentity::HermeticContent { digest } => transcript.push_str("source.hermetic", digest.as_str()),
377	        }
378	        for component in &self.components {
379	            transcript.push_str("component.kind", &component.kind);
380	            transcript.push_str("component.fingerprint", component.fingerprint.as_str());
381	        }
382	        SemanticInputDigest::from_transcript(&transcript)
383	    }
384	}
