728	fn digest_intent(
729	    snapshot: &ReleaseInputSnapshotV1,
730	    trust_profile: ExecutionTrustProfileV1,
731	    operations: &[ReleaseOperation],
732	) -> IntentDigest {
733	    let mut transcript = CanonicalTranscript::intent_v1();
734	    transcript.push_bytes("schema", [ReleaseIntentV1::SCHEMA_VERSION]);
735	    transcript.push_str("snapshot", snapshot.digest().as_str());
736	    transcript.push_str(
737	        "trust-profile",
738	        match trust_profile {
739	            ExecutionTrustProfileV1::GitCommit => "git-commit",
740	            ExecutionTrustProfileV1::HermeticContent => "hermetic-content",
741	        },
742	    );
743	    for operation in operations {
744	        transcript.push_str("operation", &operation_id_text(&operation.id));
745	        for prerequisite in &operation.prerequisites {
746	            transcript.push_str("prerequisite", &operation_id_text(prerequisite));
747	        }
748	    }
749	    IntentDigest::from_transcript(&transcript)
750	}
751	
752	fn operation_id_text(id: &ReleaseOperationId) -> String {
753	    let role = match &id.role {
754	        ReleaseOperationRole::RegistryPublish { registry } => format!(
755	            "publish:{}:{}",
756	            registry.registry_key().as_str(),
757	            registry.binding_digest().as_str()
758	        ),
759	        ReleaseOperationRole::Tag => "tag".to_string(),
760	        ReleaseOperationRole::ForgeRelease => "forge-release".to_string(),
761	    };
762	    format!("{}|{}|{}", id.package, role, id.version.render())
763	}
