765	fn validate_operations(operations: &[ReleaseOperation]) -> Result<(), ReleaseIntentError> {
766	    let mut ids = BTreeSet::new();
767	    for operation in operations {
768	        if !ids.insert(operation.id.clone()) {
769	            return Err(ReleaseIntentError::DuplicateOperation {
770	                id: Box::new(operation.id.clone()),
771	            });
772	        }
773	    }
774	    for operation in operations {
775	        if operation.prerequisites.windows(2).any(|pair| pair[0] >= pair[1]) {
776	            return Err(ReleaseIntentError::NonCanonicalPrerequisiteOrder {
777	                id: Box::new(operation.id.clone()),
778	            });
779	        }
780	        for prerequisite in &operation.prerequisites {
781	            if prerequisite == &operation.id {
782	                return Err(ReleaseIntentError::SelfPrerequisite {
783	                    id: Box::new(operation.id.clone()),
784	                });
785	            }
786	            if !ids.contains(prerequisite) {
787	                return Err(ReleaseIntentError::UnknownPrerequisite {
788	                    id: Box::new(operation.id.clone()),
789	                    prerequisite: Box::new(prerequisite.clone()),
790	                });
791	            }
792	        }
793	    }
794	    let edges: BTreeMap<_, _> = operations
795	        .iter()
796	        .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
797	        .collect();
798	    let canonical = stable_kahn_order(&edges)?;
799	    if operations.iter().map(ReleaseOperation::id).ne(canonical.iter()) {
800	        return Err(ReleaseIntentError::NonCanonicalOperationOrder);
801	    }
802	    Ok(())
803	}
