148	fn parse_release_worktree_status(status: &str) -> Result<Vec<PathBuf>, VcsError> {
149	    let mut allowed_ignored_paths = Vec::new();
150	    for record in status.split('\0').filter(|record| !record.is_empty()) {
151	        let Some(path) = record.strip_prefix("!! ") else {
152	            return Err(VcsError::Git(
153	                "release trust requires a worktree with no tracked or untracked files".to_string(),
154	            ));
155	        };
156	        let path = PathBuf::from(path);
157	        if !is_release_ignored_path_allowed(&path) {
158	            return Err(VcsError::Git(
159	                "release trust found an ignored path outside its fixed allowlist".to_string(),
160	            ));
161	        }
162	        allowed_ignored_paths.push(path);
163	    }
164	    allowed_ignored_paths.sort();
165	    allowed_ignored_paths.dedup();
166	    Ok(allowed_ignored_paths)
167	}
168	
169	fn is_release_ignored_path_allowed(path: &Path) -> bool {
170	    if path.is_absolute()
171	        || path
172	            .components()
173	            .any(|component| !matches!(component, std::path::Component::Normal(_)))
174	    {
175	        return false;
176	    }
177	    let rendered = path.to_string_lossy().replace('\\', "/");
178	    RELEASE_IGNORED_ALLOWLIST.iter().any(|allowed| {
179	        allowed.strip_suffix('/').map_or_else(
180	            || rendered == *allowed,
181	            |directory| rendered == directory || rendered.starts_with(&format!("{directory}/")),
182	        )
183	    })
184	}
