105	/// Builds a release intent from a fresh root-bound observation.
106	pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
107	    root: &Path,
108	    locator: &L,
109	    runner: &R,
110	    selection: &ReleaseSelection,
111	    trust_profile: ExecutionTrustProfileV1,
112	) -> Result<ReleaseIntentV1, GraphError> {
113	    let root = canonical_root(root)?;
114	    let workspace = Workspace::load(root.clone(), locator, runner)?;
115	    let source = observe_source(&workspace, trust_profile)?;
116	    let intent = derive_release_intent(&workspace, selection, source.clone(), trust_profile)?;
117	
118	    // Recheck after all input reads. A concurrent edit or checkout cannot be
119	    // authorized merely because it happened after the first check.
120	    if observe_source(&workspace, trust_profile)? != source {
121	        return Err(GraphError::ReleaseIntentStale);
122	    }
123	    Ok(intent)
124	}
