188	) -> Result<ReleaseIntentV1, GraphError> {
189	    let (snapshot, operations, _) = derive_release_inputs(workspace, selection, source)?;
190	    ReleaseIntentV1::new(snapshot, trust_profile, operations).map_err(|_error| GraphError::ReleaseIntentStale)
