197	    trust_profile: ExecutionTrustProfileV1,
198	) -> Result<(ReleaseIntentV1, BTreeMap<ReleaseOperationId, PreparedOperation>), GraphError> {
199	    let (snapshot, operations, prepared) = derive_release_inputs(workspace, selection, source)?;
200	    let intent =
201	        ReleaseIntentV1::new(snapshot, trust_profile, operations).map_err(|_error| GraphError::ReleaseIntentStale)?;
202	    Ok((intent, prepared))
203	}
