205	fn derive_release_inputs<R: CommandRunner, D: DependencyResolver>(
206	    workspace: &Workspace<'_, R, D>,
207	    selection: &ReleaseSelection,
208	    source: SourceIdentity,
209	) -> Result<
210	    (
211	        ReleaseInputSnapshotV1,
212	        Vec<ReleaseOperation>,
213	        BTreeMap<ReleaseOperationId, PreparedOperation>,
214	    ),
215	    GraphError,
216	> {
217	    let mut components = Vec::new();
218	    let mut kinds = BTreeSet::new();
219	
220	    let mut selected = BTreeMap::new();
221	    let mut package_ids = BTreeMap::<callisto_model::PackageId, Vec<ReleasePackageId>>::new();
222	    for package in workspace.graph.packages() {
223	        for ecosystem in package
224	            .canonical_manifests()
225	            .map(|manifest| manifest.ecosystem())
226	            .collect::<BTreeSet<_>>()
227	        {
228	            let id =
229	                ReleasePackageId::new(ecosystem, package.id.name()).map_err(|_error| GraphError::ReleaseIntentStale)?;
230	            if let Some(version) = selection.versions().get(&id) {
231	                selected.insert(id.clone(), (package, version.clone()));
232	                package_ids.entry(package.id.clone()).or_default().push(id);
233	            }
234	        }
235	    }
236	    for id in selection.versions().keys() {
237	        if !selected.contains_key(id) {
238	            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
239	        }
240	    }
241	
242	    let mut operations = BTreeMap::<ReleaseOperationId, ReleaseOperation>::new();
243	    let mut prepared = BTreeMap::<ReleaseOperationId, PreparedOperation>::new();
244	    let mut publishes_by_package = BTreeMap::<ReleasePackageId, Vec<ReleaseOperationId>>::new();
245	    let mut tag_by_package = BTreeMap::<ReleasePackageId, ReleaseOperationId>::new();
246	
247	    // First construct leaves so dependency prerequisites can refer only to
248	    // exact selected release identities, never PackageId's wildcard matcher.
249	    for (id, (package, version)) in &selected {
250	        let fingerprint = package_fingerprint(workspace, id, package, version)?;
251	        push_fingerprint(&mut components, &mut kinds, format!("package:{id}"), fingerprint);
252	
253	        let mut publishes = Vec::new();
254	        for target in &package.publish_to {
255	            if target.ecosystem() == Some(id.ecosystem()) {
256	                let registry_key = target.registry_key().expect("registry target has registry key");
257	                let binding = prepared_registry_binding(workspace, target)?;
258	                let operation = ReleaseOperation::registry_publish(
259	                    id.clone(),
260	                    version.clone(),
261	                    RegistryBindingId::new(registry_key.as_str(), binding.identity.clone())
262	                        .map_err(|_error| GraphError::ReleaseIntentStale)?,
263	                    Vec::new(),
264	                )
265	                .map_err(|_error| GraphError::ReleaseIntentStale)?;
266	                // A durable registry operation must have one exact endpoint
267	                // binding. The model-level operation identity currently has
268	                // only a registry key, so reject a second target that would
269	                // collapse to the same operation until the typed binding
270	                // identity is added there.
271	                if prepared.contains_key(operation.id()) {
272	                    return Err(GraphError::ReleaseIntentStale);
273	                }
274	                prepared.insert(
275	                    operation.id().clone(),
276	                    PreparedOperation::RegistryPublish {
277	                        package_dir: package_dir(package)?,
278	                        package_name: id.name().to_string(),
279	                        version: version.clone(),
280	                        registry: binding,
281	                        npm_access: match target {
282	                            PublishTarget::Npm { access, .. } => *access,
283	                            _ => None,
284	                        },
285	                    },
286	                );
287	                publishes.push(operation.id().clone());
288	                operations.insert(operation.id().clone(), operation);
289	            }
290	        }
291	        publishes.sort();
292	        publishes_by_package.insert(id.clone(), publishes);
293	    }
294	
295	    // Replace each publish leaf with prerequisites from selected dependency
296	    // packages. This preserves the existing publish semantics: runtime,
297	    // build, optional, and dev dependencies must exist before publish.
298	    for (id, (package, _)) in &selected {
299	        let mut prerequisites = BTreeSet::new();
300	        for edge in workspace.graph.dependencies_of(&package.id) {
301	            if !matches!(
302	                edge.kind,
303	                DepKind::Runtime | DepKind::Build | DepKind::Optional | DepKind::Dev
304	            ) {
305	                continue;
306	            }
307	            for dependency_release_id in package_ids.get(&edge.to).into_iter().flatten() {
308	                prerequisites.extend(
309	                    publishes_by_package
310	                        .get(dependency_release_id)
311	                        .into_iter()
312	                        .flatten()
313	                        .cloned(),
314	                );
315	            }
316	        }
317	        for publish_id in publishes_by_package.get(id).into_iter().flatten() {
318	            let operation = operations.get(publish_id).expect("publish operation was constructed");
319	            let replacement = ReleaseOperation::new(operation.id().clone(), prerequisites.iter().cloned().collect())
320	                .map_err(|_error| GraphError::ReleaseIntentStale)?;
321	            operations.insert(publish_id.clone(), replacement);
322	        }
323	    }
324	
325	    for (id, (package, version)) in &selected {
326	        if !package
327	            .publish_to
328	            .iter()
329	            .any(|target| !matches!(target, PublishTarget::None))
330	        {
331	            continue;
332	        }
333	        let tag = ReleaseOperation::tag(
334	            id.clone(),
335	            version.clone(),
336	            publishes_by_package.get(id).cloned().unwrap_or_default(),
337	        )
338	        .map_err(|_error| GraphError::ReleaseIntentStale)?;
339	        let tag_name = package
340	            .tag_template
341	            .clone()
342	            .unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))
343	            .render(version);
344	        let target = match &source {
345	            SourceIdentity::GitCommit { sha } => sha.clone(),
346	            SourceIdentity::HermeticContent { .. } => return Err(GraphError::ReleaseIntentStale),
347	        };
348	        prepared.insert(
349	            tag.id().clone(),
350	            PreparedOperation::Tag {
351	                annotation: format!("Release {tag_name}"),
352	                name: tag_name,
353	                target,
354	            },
355	        );
356	        tag_by_package.insert(id.clone(), tag.id().clone());
357	        operations.insert(tag.id().clone(), tag);
358	    }
359	    for (id, (package, version)) in &selected {
360	        if package
361	            .publish_to
362	            .iter()
363	            .any(|target| matches!(target, PublishTarget::GitHubRelease))
364	        {
365	            let tag = tag_by_package.get(id).expect("release point has tag").clone();
366	            let operation = ReleaseOperation::forge_release(id.clone(), version.clone(), vec![tag])
367	                .map_err(|_error| GraphError::ReleaseIntentStale)?;
368	            let tag = match prepared.get(operation.prerequisites().first().expect("forge release has tag")) {
369	                Some(PreparedOperation::Tag { name, .. }) => name.clone(),
370	                _ => return Err(GraphError::ReleaseIntentStale),
371	            };
372	            prepared.insert(operation.id().clone(), PreparedOperation::ForgeRelease { tag });
373	            operations.insert(operation.id().clone(), operation);
374	        }
375	    }
376	
377	    Ok((
378	        ReleaseInputSnapshotV1::new(source, components),
379	        canonical_operation_order(operations)?,
380	        prepared,
381	    ))
382	}
