   161	fn observe_source<R: CommandRunner, D: DependencyResolver>(
   162	    workspace: &Workspace<'_, R, D>,
   163	    trust_profile: ExecutionTrustProfileV1,
   164	) -> Result<SourceIdentity, GraphError> {
   165	    match trust_profile {
   166	        ExecutionTrustProfileV1::GitCommit => {
   167	            let evidence = workspace.git_access().observe_git_commit_trust()?;
   168	            if evidence.canonical_root() != workspace.root
   169	                || evidence.head_disposition() != GitHeadDisposition::Detached
   170	            {
   171	                return Err(GraphError::ReleaseIntentStale);
   172	            }
   173	            Ok(SourceIdentity::GitCommit {
   174	                sha: evidence.head().clone(),
   175	            })
   176	        }
   177	        // No closed-root observer exists yet. Reject rather than claim Git
   178	        // cleanliness proves a hermetic content identity.
   179	        ExecutionTrustProfileV1::HermeticContent => Err(GraphError::ReleaseIntentStale),
   180	    }
   181	}
